PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label WHERE {
  ?s rdfs:label ?label .
  FILTER (CONTAINS(?label,"ZN_2") || CONTAINS(?label,"Perimeter"))
}

PREFIX brick: <http://brickschema.org/schema/1.1/brick#>
PREFIX ref: <https://brickschema.org/schema/1.1/ref#>
SELECT ?point ?tsid WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z03> ;
         ref:hasExternalReference ?tsid .
}

PREFIX ref: <https://brickschema.org/schema/1.1/ref#>
SELECT ?point ?tsid WHERE {
  ?point ref:hasTimeseriesId ?tsid .
  FILTER (CONTAINS(STR(?point),"Zone_F1_Z03"))
}

